{'code': "from qgis.PyQt.QtWidgets import QAction
mw = iface.mainWindow()
# actions owned by QgsMapToolAdvancedDigitizing whose text contains 追加 (or Add)
found = []
for a in mw.findChildren(QAction):
    p = a.parent()
    pcls = p.__class__.__name__ if p else ''
    if 'AdvancedDigitizing' in pcls:
        t = (a.text() or '').replace('&', '')
        if '追加' in t or 'Add' in t:
            found.append({
                'objectName': a.objectName(),
                'text': a.text(),
                'isEnabled': a.isEnabled(),
                'isVisible': a.isVisible(),
                'parent_class': pcls,
            })
# also list ALL actions owned by the current map tool for context
mt = iface.mapCanvas().mapTool()
all_tool_actions = [(a.objectName(), a.text(), a.isEnabled()) for a in mt.findChildren(QAction)] if mt else []
result = {'contains_add': found, 'all_actions_of_current_tool': all_tool_actions}
"}

